any.script:
var br = tree.root.get_node_or_null("/root/Main/BoardRoot")
if br == null:
	return false
for c in br.get_children():
	var scr = c.get_script()
	if scr != null and "DisembarkController" in str(scr.resource_path):
		return true
return false

rot0.script:
var u = GameState.get_unit("U_BATTLEWAGON_T")
var ms = u.get("models", [])
if ms.is_empty():
	return 0.0
return float(ms[0].get("rotation", 0.0))

